CREATE OR REPLACE FUNCTION public.apply_profile_mutations(p_profile_id uuid, p_mutations jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare r jsonb; replies jsonb:='[]'::jsonb; fenced boolean;
begin
  perform 1 from public.profiles where id=p_profile_id and owner_id=auth.uid() for update;
  if not found then raise exception 'profile unavailable' using errcode='42501'; end if;
  if p_mutations is null or jsonb_typeof(p_mutations)<>'array'
    or jsonb_array_length(p_mutations)>100 or pg_column_size(p_mutations)>262144 then
    raise exception 'invalid mutation batch' using errcode='22023'; end if;
  select exists(select 1 from public.czn_daily_policy where profile_id=p_profile_id) into fenced;
  for r in select value from jsonb_array_elements(p_mutations) loop
    if fenced and r->>'kind'='daily' and r->'key'->>'subjectId'='dailies:czn' then
      -- No acknowledgement of success: cached old clients preserve their outbox.
      if r->>'mutationId' is null then raise exception 'invalid held mutation' using errcode='22023'; end if;
      replies:=replies||jsonb_build_array(jsonb_build_object('mutationId',r->>'mutationId','outcome','update_required'));
    else
      replies:=replies||calendar_sync_internal.apply_profile_mutations(p_profile_id,jsonb_build_array(r));
    end if;
  end loop;
  return replies;
end;
$function$
CREATE OR REPLACE FUNCTION calendar_sync_internal.apply_profile_mutations(p_profile_id uuid, p_mutations jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  row_data jsonb;
  row_kind text;
  row_key text;
  row_day text;
  row_payload jsonb;
  row_deleted boolean;
  row_unset boolean;
  row_time timestamptz;
  row_id uuid;
  old_row jsonb;
  old_time timestamptz;
  old_id uuid;
  expected_body jsonb;
  applied integer;
  answer text;
  replies jsonb := '[]'::jsonb;
begin
  if auth.uid() is null or not exists (
    select 1 from public.profiles p
    where p.id = p_profile_id and p.owner_id = auth.uid()
  ) then
    raise exception 'profile unavailable' using errcode = '42501';
  end if;
  if p_mutations is null or jsonb_typeof(p_mutations) <> 'array'
     or jsonb_array_length(p_mutations) > 100
     or pg_column_size(p_mutations) > 262144 then
    raise exception 'invalid mutation batch' using errcode = '22023';
  end if;

  for row_data in select value from jsonb_array_elements(p_mutations) loop
    if jsonb_typeof(row_data) <> 'object'
       or row_data->>'changedAt' !~
         '^[0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}:[0-9]{2}(\.[0-9]{1,3})?(Z|[+-][0-9]{2}:[0-9]{2})$'
       or row_data->>'mutationId' is null then
      raise exception 'invalid mutation envelope' using errcode = '22023';
    end if;
    row_kind := row_data->>'kind';
    row_time := (row_data->>'changedAt')::timestamptz;
    row_id := (row_data->>'mutationId')::uuid;
    applied := null;
    old_row := null;

    case row_kind
      when 'progress' then
        row_key := row_data->>'key';
        if coalesce(length(row_key), 0) not between 1 and 512
           or jsonb_typeof(row_data->'deleted') <> 'boolean' then
          raise exception 'invalid progress key or deletion state' using errcode = '22023';
        end if;
        row_deleted := (row_data->>'deleted')::boolean;
        row_payload := row_data->'payload';
        if row_payload is null or row_deleted <> (row_payload = 'null'::jsonb) or
           (not row_deleted and (jsonb_typeof(row_payload) <> 'object'
             or not (row_payload ?& array['status','effort','daily','note'])
             or jsonb_typeof(row_payload->'daily') not in ('boolean','null')
             or jsonb_typeof(row_payload->'note') not in ('string','null'))) then
          raise exception 'invalid progress payload' using errcode = '22023';
        end if;
        insert into public.progress as current
          (profile_id,event_id,status,effort,daily_override,note,deleted,changed_at,mutation_id)
          values (p_profile_id,row_key,
            case when row_deleted then null else row_payload->>'status' end,
            case when row_deleted then null else row_payload->>'effort' end,
            case when row_deleted or row_payload->'daily' = 'null'::jsonb then null
              else (row_payload->>'daily')::boolean end,
            case when row_deleted then null else row_payload->>'note' end,
            row_deleted,row_time,row_id)
          on conflict (profile_id,event_id) do update set
            status=excluded.status, effort=excluded.effort,
            daily_override=excluded.daily_override, note=excluded.note,
            deleted=excluded.deleted, changed_at=excluded.changed_at,
            mutation_id=excluded.mutation_id, received_at=now()
          where (excluded.changed_at,excluded.mutation_id) >
            (current.changed_at,current.mutation_id)
          returning 1 into applied;
        if applied is null then
          select to_jsonb(t), t.changed_at, t.mutation_id into old_row, old_time, old_id
            from public.progress t where t.profile_id=p_profile_id and t.event_id=row_key;
          expected_body := jsonb_build_object('event_id',row_key,
            'status',case when row_deleted then null else row_payload->>'status' end,
            'effort',case when row_deleted then null else row_payload->>'effort' end,
            'daily_override',case when row_deleted or row_payload->'daily'='null'::jsonb
              then null else (row_payload->>'daily')::boolean end,
            'note',case when row_deleted then null else row_payload->>'note' end,
            'deleted',row_deleted);
        end if;

      when 'daily' then
        row_key := row_data->'key'->>'subjectId';
        row_day := row_data->'key'->>'dayKey';
        if coalesce(length(row_key),0) not between 1 and 512
           or row_day !~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}$'
           or jsonb_typeof(row_data->'completed') <> 'boolean' then
          raise exception 'invalid daily mutation' using errcode = '22023';
        end if;
        insert into public.daily_marks as current
          (profile_id,subject_id,day_key,completed,changed_at,mutation_id)
          values (p_profile_id,row_key,row_day,(row_data->>'completed')::boolean,row_time,row_id)
          on conflict (profile_id,subject_id,day_key) do update set
            completed=excluded.completed, changed_at=excluded.changed_at,
            mutation_id=excluded.mutation_id, received_at=now()
          where (excluded.changed_at,excluded.mutation_id) >
            (current.changed_at,current.mutation_id)
          returning 1 into applied;
        if applied is null then
          select to_jsonb(t), t.changed_at, t.mutation_id into old_row, old_time, old_id
            from public.daily_marks t where t.profile_id=p_profile_id
              and t.subject_id=row_key and t.day_key=row_day;
          expected_body := jsonb_build_object('subject_id',row_key,
            'day_key',row_day,'completed',(row_data->>'completed')::boolean);
        end if;

      when 'ignored' then
        row_key := row_data->>'key';
        if coalesce(length(row_key),0) not between 1 and 512
           or jsonb_typeof(row_data->'ignored') <> 'boolean' then
          raise exception 'invalid ignored mutation' using errcode = '22023';
        end if;
        insert into public.ignored as current
          (profile_id,event_id,ignored,changed_at,mutation_id)
          values (p_profile_id,row_key,(row_data->>'ignored')::boolean,row_time,row_id)
          on conflict (profile_id,event_id) do update set
            ignored=excluded.ignored,changed_at=excluded.changed_at,
            mutation_id=excluded.mutation_id,received_at=now()
          where (excluded.changed_at,excluded.mutation_id) >
            (current.changed_at,current.mutation_id)
          returning 1 into applied;
        if applied is null then
          select to_jsonb(t), t.changed_at, t.mutation_id into old_row, old_time, old_id
            from public.ignored t where t.profile_id=p_profile_id and t.event_id=row_key;
          expected_body := jsonb_build_object('event_id',row_key,
            'ignored',(row_data->>'ignored')::boolean);
        end if;

      when 'preference' then
        row_key := row_data->>'key';
        row_payload := row_data->'value';
        if jsonb_typeof(row_data->'unset') <> 'boolean' or row_payload is null
           or not public.sync_valid_preference(row_key,row_payload,
             (row_data->>'unset')::boolean) then
          raise exception 'invalid preference mutation' using errcode = '22023';
        end if;
        row_unset := (row_data->>'unset')::boolean;
        insert into public.preferences as current
          (profile_id,key,value,unset,changed_at,mutation_id)
          values (p_profile_id,row_key,row_payload,row_unset,row_time,row_id)
          on conflict (profile_id,key) do update set
            value=excluded.value,unset=excluded.unset,changed_at=excluded.changed_at,
            mutation_id=excluded.mutation_id,received_at=now()
          where (excluded.changed_at,excluded.mutation_id) >
            (current.changed_at,current.mutation_id)
          returning 1 into applied;
        if applied is null then
          select to_jsonb(t), t.changed_at, t.mutation_id into old_row, old_time, old_id
            from public.preferences t where t.profile_id=p_profile_id and t.key=row_key;
          expected_body := jsonb_build_object('key',row_key,'value',row_payload,'unset',row_unset);
        end if;

      when 'customGame', 'customEvent' then
        row_key := row_data->>'key';
        row_payload := row_data->'payload';
        if jsonb_typeof(row_data->'deleted') <> 'boolean' then
          raise exception 'invalid custom deletion state' using errcode = '22023';
        end if;
        row_deleted := (row_data->>'deleted')::boolean;
        if row_payload is null or row_deleted <> (row_payload = 'null'::jsonb) or
           (not row_deleted and (jsonb_typeof(row_payload) <> 'object'
             or row_payload->>'id' is distinct from row_key)) then
          raise exception 'invalid custom payload' using errcode = '22023';
        end if;
        if row_kind = 'customGame' then
          if not row_deleted and (not (row_payload ?& array['id','name','hue','at'])
             or jsonb_typeof(row_payload->'name') <> 'string'
             or jsonb_typeof(row_payload->'hue') <> 'string'
             or jsonb_typeof(row_payload->'at') <> 'string') then
            raise exception 'invalid custom game envelope' using errcode = '22023';
          end if;
          insert into public.custom_games as current
            (profile_id,local_id,payload,deleted,changed_at,mutation_id)
            values (p_profile_id,row_key,
              case when row_deleted then null else row_payload end,row_deleted,row_time,row_id)
            on conflict (profile_id,local_id) do update set
              payload=excluded.payload,deleted=excluded.deleted,
              changed_at=excluded.changed_at,mutation_id=excluded.mutation_id,received_at=now()
            where (excluded.changed_at,excluded.mutation_id) >
              (current.changed_at,current.mutation_id)
            returning 1 into applied;
          if applied is null then
            select to_jsonb(t), t.changed_at, t.mutation_id into old_row, old_time, old_id
              from public.custom_games t where t.profile_id=p_profile_id and t.local_id=row_key;
          end if;
        else
          if not row_deleted and (not (row_payload ?& array[
              'id','game','title','type','startsAt','startPrecision','endsAt',
              'endPrecision','repeat','at','updatedAt'])
             or jsonb_typeof(row_payload->'game') <> 'string'
             or jsonb_typeof(row_payload->'title') <> 'string'
             or jsonb_typeof(row_payload->'type') <> 'string') then
            raise exception 'invalid custom event envelope' using errcode = '22023';
          end if;
          insert into public.custom_events as current
            (profile_id,local_id,payload,deleted,changed_at,mutation_id)
            values (p_profile_id,row_key,
              case when row_deleted then null else row_payload end,row_deleted,row_time,row_id)
            on conflict (profile_id,local_id) do update set
              payload=excluded.payload,deleted=excluded.deleted,
              changed_at=excluded.changed_at,mutation_id=excluded.mutation_id,received_at=now()
            where (excluded.changed_at,excluded.mutation_id) >
              (current.changed_at,current.mutation_id)
            returning 1 into applied;
          if applied is null then
            select to_jsonb(t), t.changed_at, t.mutation_id into old_row, old_time, old_id
              from public.custom_events t where t.profile_id=p_profile_id and t.local_id=row_key;
          end if;
        end if;
        if applied is null then
          expected_body := jsonb_build_object('local_id',row_key,
            'payload',case when row_deleted then null else row_payload end,
            'deleted',row_deleted);
        end if;

      else
        raise exception 'unknown mutation kind' using errcode = '22023';
    end case;

    if applied is not null then
      answer := 'accepted';
    elsif old_id = row_id and old_time <> row_time then
      raise exception 'mutation ID reused with a different version' using errcode = '22023';
    elsif old_time = row_time and old_id = row_id then
      if (old_row - 'profile_id' - 'changed_at' - 'mutation_id' - 'received_at')
         is distinct from expected_body then
        raise exception 'conflicting payload for logical version' using errcode = '22023';
      end if;
      answer := 'accepted';
    else
      answer := 'superseded';
    end if;
    replies := replies || jsonb_build_array(
      jsonb_build_object('mutationId',row_id,'outcome',answer));
  end loop;
  return replies;
end;
$function$
CREATE OR REPLACE FUNCTION public.czn_daily_apply(p_profile_id uuid, p_epoch uuid, p_mutations jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare policy public.czn_daily_policy; r jsonb; old public.czn_daily_marks;
  d text; t timestamptz; mid uuid; done boolean; replies jsonb:='[]'::jsonb; outcome text;
begin
  perform 1 from public.profiles where id=p_profile_id and owner_id=auth.uid() for update;
  if not found then raise exception 'profile unavailable' using errcode='42501'; end if;
  select * into policy from public.czn_daily_policy where profile_id=p_profile_id;
  if policy.epoch is null or policy.epoch is distinct from p_epoch then
    raise exception 'CZN epoch mismatch' using errcode='22023'; end if;
  if not (select enabled from public.czn_daily_release where singleton) then
    raise exception 'CZN policy read-only' using errcode='55000'; end if;
  if p_mutations is null or jsonb_typeof(p_mutations)<>'array'
    or jsonb_array_length(p_mutations)>100 or pg_column_size(p_mutations)>262144 then
    raise exception 'invalid mutation batch' using errcode='22023'; end if;
  for r in select value from jsonb_array_elements(p_mutations) loop
    if jsonb_typeof(r)<>'object' or
      not(r ?& array['policyId','subjectId','dayKey','completed','changedAt','mutationId']) or
      (select count(*) from jsonb_object_keys(r))<>6 or
      r->>'policyId' is distinct from policy.policy_id or r->>'subjectId' is distinct from 'dailies:czn' or
      jsonb_typeof(r->'completed') is distinct from 'boolean' or
      coalesce(r->>'changedAt','') !~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}:[0-9]{2}(\.[0-9]{1,3})?(Z|[+-][0-9]{2}:[0-9]{2})$' or
      coalesce(r->>'dayKey','') !~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}$' or r->>'mutationId' is null then
      raise exception 'invalid CZN mutation' using errcode='22023'; end if;
    d:=r->>'dayKey'; t:=(r->>'changedAt')::timestamptz; mid:=(r->>'mutationId')::uuid; done:=(r->>'completed')::boolean;
    if d::date::text<>d or t in ('infinity','-infinity') or
      d < ((policy.cutover_at at time zone 'UTC')-interval '18 hours')::date::text or
      d > ((clock_timestamp() at time zone 'UTC')-interval '18 hours')::date::text then
      raise exception 'CZN date outside policy window' using errcode='22023'; end if;
    select * into old from public.czn_daily_marks where profile_id=p_profile_id
      and policy_id=policy.policy_id and subject_id='dailies:czn' and day_key=d;
    if old.mutation_id=mid and (old.changed_at<>t or old.completed<>done) then
      raise exception 'conflicting CZN mutation ID' using errcode='22023'; end if;
    if old.mutation_id is null or (t,mid)>(old.changed_at,old.mutation_id) then
      insert into public.czn_daily_marks values(p_profile_id,policy.policy_id,p_epoch,'dailies:czn',d,done,t,mid,now())
        on conflict(profile_id,policy_id,subject_id,day_key) do update set
          completed=excluded.completed,changed_at=excluded.changed_at,mutation_id=excluded.mutation_id,received_at=excluded.received_at;
      outcome:='accepted';
    else outcome:=case when (t,mid)=(old.changed_at,old.mutation_id) then 'accepted' else 'superseded' end;
    end if;
    replies:=replies||jsonb_build_array(jsonb_build_object('mutationId',mid,'outcome',outcome));
  end loop;
  return replies;
end;
$function$
CREATE OR REPLACE FUNCTION public.czn_daily_negotiate(p_profile_id uuid, p_cutover boolean DEFAULT false)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare result jsonb; available boolean;
begin
  perform 1 from public.profiles where id=p_profile_id and owner_id=auth.uid() for update;
  if not found then raise exception 'profile unavailable' using errcode='42501'; end if;
  select enabled into available from public.czn_daily_release where singleton;
  if p_cutover and available then
    insert into public.czn_daily_policy(profile_id) values(p_profile_id) on conflict do nothing;
  end if;
  select jsonb_build_object('policyId',policy_id,'epoch',epoch,'cutoverAt',cutover_at)
    into result from public.czn_daily_policy where profile_id=p_profile_id;
  return jsonb_build_object('protocol',2,'enabled',available,'policy',result);
end;
$function$
CREATE OR REPLACE FUNCTION public.daily_pass_apply(p_profile_id uuid, p_ops jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  uuid_re constant text := '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$';
  instant_re constant text :=
    '^[0-9]{4}-[0-9]{2}-[0-9]{2}T([01][0-9]|2[0-3]):[0-5][0-9]:[0-5][0-9](\.[0-9]{1,3})?(Z|[+-](0[0-9]|1[0-4]):[0-5][0-9])$';
  r jsonb;
  v_kind text;
  v_keys integer;
  v_id uuid;
  v_created timestamptz;
  v_days integer;
  v_last text;
  v_target uuid;
  v_based uuid[];
  v_resolution text;
  inserted integer;
  existing public.daily_pass_ops;
  replies jsonb := '[]'::jsonb;
begin
  if auth.uid() is null or not exists (
    select 1 from public.profiles p where p.id = p_profile_id and p.owner_id = auth.uid()
  ) then
    raise exception 'profile unavailable' using errcode = '42501';
  end if;
  if p_ops is null or jsonb_typeof(p_ops) <> 'array'
     or jsonb_array_length(p_ops) > 100 or pg_column_size(p_ops) > 262144 then
    raise exception 'invalid daily pass batch' using errcode = '22023';
  end if;

  for r in select value from jsonb_array_elements(p_ops) loop
    if jsonb_typeof(r) is distinct from 'object' then
      raise exception 'invalid daily pass op' using errcode = '22023';
    end if;
    v_kind := r->>'kind';
    v_keys := case v_kind when 'extend' then 7 when 'set' then 8 when 'undo' then 7 when 'resolve' then 8 else -1 end;
    if v_keys < 0 or (select count(*) from jsonb_object_keys(r)) <> v_keys
       or not (r ?& array['opId', 'game', 'region', 'kind', 'actionDay', 'createdAt'])
       or jsonb_typeof(r->'opId') is distinct from 'string' or (r->>'opId') !~ uuid_re
       or jsonb_typeof(r->'game') is distinct from 'string' or not public.daily_pass_valid_game(r->>'game')
       or jsonb_typeof(r->'region') is distinct from 'string' or (r->>'region') not in ('america', 'europe', 'asia')
       or jsonb_typeof(r->'actionDay') is distinct from 'string' or not public.daily_pass_valid_day(r->>'actionDay')
       or jsonb_typeof(r->'createdAt') is distinct from 'string' or (r->>'createdAt') !~ instant_re
       or not public.daily_pass_valid_day(left(r->>'createdAt', 10)) then
      raise exception 'invalid daily pass op' using errcode = '22023';
    end if;
    v_id := (r->>'opId')::uuid;
    v_created := (r->>'createdAt')::timestamptz;
    -- The written date is checked above; the UTC-normalized instant must also stay
    -- inside the table's margin (9999-12-31T23:59:59-14:00 is year 10000 in UTC).
    if extract(epoch from v_created) not between -62135510400 and 253402214399.999999 then
      raise exception 'invalid daily pass op' using errcode = '22023';
    end if;
    -- A device clock days in the future must not inflate an expiry.
    if (r->>'actionDay')::date > (clock_timestamp() at time zone 'UTC')::date + 1 then
      raise exception 'daily pass action day is in the future' using errcode = '22023';
    end if;
    v_days := null; v_last := null; v_target := null; v_based := null; v_resolution := null;
    case v_kind
      when 'extend' then
        if jsonb_typeof(r->'days') is distinct from 'number' or (r->>'days') !~ '^[0-9]{1,3}$'
           or (r->>'days')::int not between 1 and 180 then
          raise exception 'invalid daily pass extend' using errcode = '22023';
        end if;
        v_days := (r->>'days')::int;
      when 'set' then
        if not (r ? 'lastDay' and r ? 'basedOn')
           or (jsonb_typeof(r->'lastDay') <> 'null' and (jsonb_typeof(r->'lastDay') <> 'string'
             or not public.daily_pass_valid_day(r->>'lastDay')))
           or jsonb_typeof(r->'basedOn') is distinct from 'array' or jsonb_array_length(r->'basedOn') > 500
           or exists (select 1 from jsonb_array_elements(r->'basedOn') e
             where jsonb_typeof(e) <> 'string' or (e #>> '{}') !~ uuid_re)
           or (select count(distinct e #>> '{}') from jsonb_array_elements(r->'basedOn') e)
             <> jsonb_array_length(r->'basedOn') then
          raise exception 'invalid daily pass set' using errcode = '22023';
        end if;
        v_last := r->>'lastDay';
        v_based := array(select (e #>> '{}')::uuid from jsonb_array_elements(r->'basedOn') e order by 1);
      when 'undo', 'resolve' then
        if jsonb_typeof(r->'targetOp') is distinct from 'string' or (r->>'targetOp') !~ uuid_re
           or (r->>'targetOp') = (r->>'opId')
           or (v_kind = 'resolve' and (jsonb_typeof(r->'resolution') is distinct from 'string'
             or (r->>'resolution') not in ('include', 'exclude'))) then
          raise exception 'invalid daily pass target' using errcode = '22023';
        end if;
        v_target := (r->>'targetOp')::uuid;
        v_resolution := case when v_kind = 'resolve' then r->>'resolution' end;
    end case;

    insert into public.daily_pass_ops (profile_id, op_id, game, region, kind, action_day,
      created_at, days, last_day, target_op, based_on, resolution)
      values (p_profile_id, v_id, r->>'game', r->>'region', v_kind, r->>'actionDay',
        v_created, v_days, v_last, v_target, v_based, v_resolution)
      on conflict (profile_id, op_id) do nothing;
    get diagnostics inserted = row_count;
    if inserted = 0 then
      select * into existing from public.daily_pass_ops where profile_id = p_profile_id and op_id = v_id;
      if not found then
        raise exception 'concurrent daily pass op not visible; retry' using errcode = '40001';
      end if;
      if (existing.game, existing.region, existing.kind, existing.action_day, existing.created_at, existing.days,
          existing.last_day, existing.target_op, existing.based_on, existing.resolution) is distinct from
         (r->>'game', r->>'region', v_kind, r->>'actionDay', v_created, v_days,
          v_last, v_target, v_based, v_resolution) then
        raise exception 'daily pass op ID reused with different content' using errcode = '22023';
      end if;
    end if;
    replies := replies || jsonb_build_array(jsonb_build_object('opId', v_id, 'outcome', 'accepted'));
  end loop;
  return replies;
end;
$function$
CREATE OR REPLACE FUNCTION public.daily_pass_ops_immutable()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
begin
  raise exception 'daily pass ops are immutable' using errcode = '55000';
end;
$function$
CREATE OR REPLACE FUNCTION public.daily_pass_valid_day(day text)
 RETURNS boolean
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO ''
AS $function$
begin
  return coalesce(day ~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}$'
    and make_date(substr(day, 1, 4)::int, substr(day, 6, 2)::int, substr(day, 9, 2)::int) is not null, false);
exception when others then
  return false;
end;
$function$
CREATE OR REPLACE FUNCTION public.daily_pass_valid_game(game text)
 RETURNS boolean
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO ''
AS $function$
  select coalesce((game ~ '^[a-z][a-z0-9]{0,31}$' and game not in ('dailies', 'mygame', 'myevent'))
    or game ~ '^mygame:[a-z0-9-]{1,60}$', false);
$function$
CREATE OR REPLACE FUNCTION public.ensure_default_profile()
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  account_id uuid := auth.uid();
  result_id uuid;
begin
  if account_id is null then
    raise exception 'authentication required' using errcode = '42501';
  end if;
  insert into public.profiles (owner_id, name, is_default)
    values (account_id, 'Default', true)
    on conflict (owner_id) where is_default do nothing
    returning id into result_id;
  if result_id is null then
    select id into result_id from public.profiles
      where owner_id = account_id and is_default;
  end if;
  if result_id is null then
    raise exception 'default profile unavailable';
  end if;
  return result_id;
end;
$function$
CREATE OR REPLACE FUNCTION public.sync_text_array(value jsonb, allowed text[] DEFAULT NULL::text[])
 RETURNS boolean
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO ''
AS $function$
  select jsonb_typeof(value) = 'array' and not exists (
    select 1 from jsonb_array_elements(
      case when jsonb_typeof(value) = 'array' then value else '[]'::jsonb end
    ) as item(element)
    where jsonb_typeof(item.element) <> 'string'
       or (allowed is not null and not ((item.element #>> '{}') = any(allowed)))
  );
$function$
CREATE OR REPLACE FUNCTION public.sync_valid_preference(pref_key text, pref_value jsonb, pref_unset boolean)
 RETURNS boolean
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO ''
AS $function$
  select case
    when pref_unset then pref_key in ('knownGames', 'gameOrder')
      and pref_value = 'null'::jsonb
    when pref_key in ('hiddenGames', 'knownGames', 'gameOrder') then
      public.sync_text_array(pref_value)
    when pref_key = 'visibleCategories' then public.sync_text_array(pref_value,
      array['banner','event','challenge','login','shop','maintenance'])
    when pref_key = 'focusGame' then jsonb_typeof(pref_value) in ('string', 'null')
    when pref_key = 'region' then pref_value::text in ('"america"','"europe"','"asia"')
    when pref_key = 'sort' then pref_value::text in ('"ending"','"doing"')
    when pref_key = 'view' then pref_value::text in ('"soon"','"timeline"')
    when pref_key = 'timelineGroup' then pref_value::text in ('"game"','"ending"')
    when pref_key = 'theme' then pref_value::text in ('"dark"','"light"','"system"')
    when pref_key = 'timelineDayWidth' then jsonb_typeof(pref_value) = 'number'
    when pref_key in ('showUpcoming','timelineSplitUpcoming','detectDaily',
      'showChores','showCompleted','showIgnored','regionConfirmed','onboarded')
      then jsonb_typeof(pref_value) = 'boolean'
    else false
  end;
$function$
